WITH RECURSIVE sub AS (
  SELECT id FROM categories WHERE id = 2
  UNION ALL
  SELECT c.id FROM categories c JOIN sub s ON c.parent_id = s.id
)
SELECT id FROM sub;

SELECT c.name
FROM customers c
JOIN orders o ON o.customer_id = c.id;

