INSERT INTO stock (sku, qty) VALUES ('A1', 3), ('B2', 4)
ON CONFLICT (sku) DO UPDATE SET qty = stock.qty + excluded.qty;

SELECT sku, qty FROM stock ORDER BY sku;

CREATE TABLE order_lines (
  qty        int            NOT NULL,
  unit_price numeric(10,2)  NOT NULL,
  total      numeric(12,2)  GENERATED ALWAYS AS (qty * unit_price) STORED
);

CREATE TABLE promo (
  code     text PRIMARY KEY,
  discount int  CHECK (discount BETWEEN 1 AND 100)
);
