SELECT id FROM (
  SELECT id, ROW_NUMBER() OVER (
    PARTITION BY customer_id ORDER BY created_at DESC) AS rn
  FROM o WHERE status = 'paid'
) t WHERE rn = 1;

WITH moved AS (
  DELETE FROM orders
  WHERE created_at < now() - interval '2 years'
  RETURNING *
)
INSERT INTO orders_archive SELECT * FROM moved;

